@ResponseStatus(HttpStatus.NOT_FOUND)
public class ResourceNotFoundException extends RuntimeException {

    public ResourceNotFoundException(String message) {
        super(message);
    }
}

@ExceptionHandler(ResourceNotFoundException.class)
public ResponseEntity<ErrorResponse> handleResourceNotFound(
  ResourceNotFoundException ex) {
  // El recurso solicitado no existe.
  return ResponseEntity
    .status(HttpStatus.NOT_FOUND)
    .body(new ErrorResponse(ex.getMessage()));
}

public class ResourceNotFoundException extends RuntimeException {

    public ResourceNotFoundException(String message) {
        super(message);
    }
}

public class ConflictException extends RuntimeException {

  public ConflictException(String message) {
    super(message);
  }
}

@ExceptionHandler(MethodArgumentNotValidException.class)
public ResponseEntity<ErrorResponse> handleValidation(
        MethodArgumentNotValidException ex) {
    String message = ex.getBindingResult()
            .getFieldErrors()
            .stream()
            .findFirst()
            .map(FieldError::getDefaultMessage)
            .orElse("El objeto json es inválido.");

    return ResponseEntity.badRequest()
            .body(new ErrorResponse(message));
}

@ExceptionHandler(ConstraintViolationException.class)
public ResponseEntity<ErrorResponse> handleConstraintViolation(
        ConstraintViolationException ex) {
    // Maneja validaciones de @RequestParam y @PathVariable
    String message = ex.getConstraintViolations()
            .stream()
            .findFirst()
            .map(ConstraintViolation::getMessage)
            .orElse("Solicitud invválido, el valor de los parametros no cumplen");

    return ResponseEntity.badRequest()
            .body(new ErrorResponse(message));
}

@ExceptionHandler(HttpMessageNotReadableException.class)
public ResponseEntity<ErrorResponse> handleUnreadableMessage(
        HttpMessageNotReadableException ex) {
     return ResponseEntity.badRequest()
            .body(new ErrorResponse("El objeto json es inválido. Intente de nuevo"));
}

@ExceptionHandler(BusinessException.class)
public ResponseEntity<ErrorResponse> handleBusinessException(
        BusinessException ex) {
    return ResponseEntity.badRequest()
            .body(new ErrorResponse(ex.getMessage()));
}

@ExceptionHandler(ConflictException.class)
public ResponseEntity<ErrorResponse> handleConflictException(
        ConflictException ex) {
    return ResponseEntity.status(HttpStatus.CONFLICT)
            .body(new ErrorResponse(ex.getMessage()));
}

@ExceptionHandler(Exception.class)
public ResponseEntity<ErrorResponse> handleInternalServerException(
        Exception ex) {
    return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
            .body(new ErrorResponse("Internal server error"));
}
